        clauses.append([var(v, 0), var(v, 1), var(v, 2)])
        clauses += [[-var(v, a), -var(v, b)] for a, b in ((0, 1), (0, 2), (1, 2))]
        clauses += [[-var(v, c), -var(w, c)] for w in vertices(adj[v]) if w > v for c in range(3)]
